// tsserver plugin: a call into a sibling workspace package resolves to its sources in a checkout neither installed nor
// built. Core hands it {root, members} through `_typescript.configurePlugin` (static_analyzer/typescript_workspace.py).
//  1. Links: a lookup under <dir>/node_modules/<member> answers from the member's folder, as an install links it.
//  2. References: a project references the configs of each member it imports, so TypeScript's own
//     source-of-project-reference redirect maps the member's missing build output (outDir) back to its sources.
//  3. An entry no config emits (a bundler builds it) is read as its source under src/, as Knip maps it.
"use strict";
const fs = require("fs");
const path = require("path");

const HOOKED = Symbol("codeboarding-workspace-sources");
// <before>/node_modules/<package name><rest>, the last node_modules segment.
const NODE_MODULES_PATH = /^(.*)\/node_modules\/((?:@[^/]+\/)?[^/@][^/]*)(\/.*)?$/;
// The package a module specifier names: `from "x"`, `import "x"`, `import("x")`, `require("x")`.
const SPECIFIER = /(?:\bfrom\s*|\bimport\s*\(\s*|\brequire\s*\(\s*|\bimport\s+)["'`]((?:@[^/"'`]+\/)?[^./"'`@][^/"'`]*)/g;
const ENTRY_FIELDS = ["main", "module", "types", "typings", "exports"];
const SOURCE_EXTENSIONS = [".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"];

// Forward slashes and a lower-case drive letter, as tsserver spells a path.
const norm = (file) => file.replace(/\\/g, "/").replace(/^[A-Z]:/, (drive) => drive.toLowerCase());

function linkMembers(host, root, members) {
  const linked = (file) => {
    const match = typeof file === "string" && norm(file).startsWith(`${root}/`) && NODE_MODULES_PATH.exec(norm(file));
    const folder = match && members.get(match[2]);
    return folder ? folder + (match[3] || "") : null;
  };
  // Why: module resolution skips a node_modules folder that is not on disk; an install hoists the links to the root.
  const scopes = [...members.keys()].filter((name) => name.startsWith("@")).map((name) => name.split("/")[0]);
  const linkParents = new Set([`${root}/node_modules`, ...scopes.map((scope) => `${root}/node_modules/${scope}`)]);
  const manifests = new Map([...members.values()].map((folder) => [`${folder}/package.json`, folder]));
  for (const name of ["fileExists", "realpath"]) {
    const original = host[name];
    if (typeof original === "function") host[name] = (file, ...rest) => original.call(host, linked(file) || file, ...rest);
  }
  const { readFile, directoryExists } = host;
  host.readFile = (file, ...rest) => {
    const target = linked(file) || file;
    const text = readFile.call(host, target, ...rest);
    const folder = text !== undefined && typeof target === "string" && manifests.get(norm(target));
    return folder ? withSources(text, folder) : text;
  };
  host.directoryExists = (dir) => {
    const target = linked(dir);
    if (target) return directoryExists.call(host, target);
    return directoryExists.call(host, dir) || (typeof dir === "string" && linkParents.has(norm(dir)));
  };
}

// *text*, a member's package.json, with each entry missing from disk read as its source under src/ when there is one.
function withSources(text, folder) {
  let manifest;
  try {
    manifest = JSON.parse(text);
  } catch (error) {
    return text;
  }
  const source = (entry) => {
    if (fs.existsSync(path.resolve(folder, entry))) return entry;
    const stem = entry.replace(/^(\.\/)?[^/]+\//, "src/").replace(/(\.d)?\.[cm]?[jt]sx?$/, "");
    const found = SOURCE_EXTENSIONS.map((extension) => stem + extension).find((file) => fs.existsSync(path.resolve(folder, file)));
    return found ? `./${found}` : entry;
  };
  const replace = (value) => {
    if (typeof value === "string") return source(value);
    if (Array.isArray(value)) return value.map(replace);
    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, nested]) => [key, replace(nested)]));
    return value;
  };
  for (const field of ENTRY_FIELDS) if (field in manifest) manifest[field] = replace(manifest[field]);
  return JSON.stringify(manifest);
}

function referenceMembers(project, host, members, configured) {
  const own = configured ? norm(project.getProjectName()) : null;
  const original = host.getProjectReferences;
  const scanned = new Set();
  const used = new Set();
  let added = [];
  // Why scanned as files join, not at create: tsserver enables plugins before it adds a project's root files.
  host.getProjectReferences = () => {
    const declared = (typeof original === "function" && original.call(host)) || [];
    const files = project.getRootFiles().filter((file) => !scanned.has(file));
    if (files.length) {
      for (const file of files) {
        scanned.add(file);
        try {
          for (const match of fs.readFileSync(file, "utf8").matchAll(SPECIFIER)) used.add(match[1]);
        } catch (error) {
          continue;
        }
      }
      // Every tsconfig and jsconfig of each member. Why every one: the redirect then finds whichever emits an entry.
      const have = new Set(declared.map((reference) => norm(path.resolve(reference.path))));
      const folders = [...used].map((name) => members.get(name)).filter((folder) => folder && !have.has(folder));
      added = folders
        .flatMap((folder) => fs.readdirSync(folder).filter((file) => /^[tj]sconfig.*\.json$/.test(file)).sort().map((file) => `${folder}/${file}`))
        .filter((config) => config !== own && !have.has(config))
        .map((config) => ({ path: config }));
    }
    return declared.length || added.length ? [...declared, ...added] : undefined;
  };
  if (!configured && typeof host.getCompilerHost !== "function") {
    // An inferred project has no references of its own, so tsserver gives it neither the redirect nor the compiler
    // host the redirect answers module resolution through. Both as a configured project has them.
    let compilerHost;
    host.setCompilerHost = (created) => {
      compilerHost = created;
    };
    host.getCompilerHost = () => compilerHost;
    host.useSourceOfProjectReferenceRedirect = () => added.length > 0;
  }
}

module.exports = function init({ typescript: ts }) {
  return {
    create(info) {
      const host = info.languageServiceHost;
      const { root, members } = info.config || {};
      if (!root || !members || host[HOOKED]) return info.languageService;
      host[HOOKED] = true;
      const folders = new Map(Object.entries(members).map(([name, folder]) => [name, norm(folder)]));
      linkMembers(host, norm(root), folders);
      const kind = info.project.projectKind;
      if (kind === ts.server.ProjectKind.Configured || kind === ts.server.ProjectKind.Inferred) {
        referenceMembers(info.project, host, folders, kind === ts.server.ProjectKind.Configured);
      }
      info.project.projectService.logger.info(`codeboarding-workspace-sources: ${folders.size} members under ${root}`);
      return info.languageService;
    },
  };
};
